changeSet.sql:


 UPDATE m_loan
 SET product_id = (select max(id) from m_product_loan mpl where close_date is null)
 WHERE product_id IN (
     SELECT id
     FROM m_product_loan mpl
     WHERE UPPER(NAME) LIKE '%DISABLED%'
 );

DELETE FROM m_product_loan_configurable_attributes WHERE loan_product_id IN (
     SELECT id
     FROM m_product_loan mpl
     WHERE UPPER(NAME) LIKE '%DISABLED%'
 );

DELETE FROM m_loan_product_payment_allocation_rule WHERE loan_product_id IN (
     SELECT id
     FROM m_product_loan mpl
     WHERE UPPER(NAME) LIKE '%DISABLED%'
 );

DELETE FROM m_product_loan_charge WHERE product_loan_id IN (
     SELECT id
     FROM m_product_loan mpl
     WHERE UPPER(NAME) LIKE '%DISABLED%'
 );

DELETE FROM m_loan_product_channel WHERE loan_product_id IN (
     SELECT id
     FROM m_product_loan mpl
     WHERE UPPER(NAME) LIKE '%DISABLED%'
 );

DELETE FROM m_product_loan_recalculation_details WHERE product_id IN (
     SELECT id
     FROM m_product_loan mpl
     WHERE UPPER(NAME) LIKE '%DISABLED%'
 );

DELETE FROM m_product_loan WHERE UPPER(NAME) LIKE '%DISABLED%';
